from construire import Chapter,fig,box,qs,sub
from nouveaux_communs import diagnostic,exercices,bilan
from math import pi,sqrt

def create():
 c=Chapter(10,'Ondes stationnaires et corde vibrante','approfondissement de 1.6','un approfondissement sur les ondes stationnaires, les conditions aux limites et les modes propres d’une corde, à partir des outils de superposition.')
 c.f('stationnaire',r'''\begin{axis}[width=13.4cm,height=5.8cm,xmin=0,xmax=1,ymin=-1.2,ymax=1.2,xlabel={$x/L$},ylabel={$y/A_3$},axis lines=left,grid=major,legend style={draw=none,at={(.5,1.04)},anchor=south,legend columns=3,font=\small}]\addplot[otNavy,thick,domain=0:1,samples=220]{sin(deg(3*pi*x))};\addlegendentry{$t=0$}\addplot[otGreenDark,thick,domain=0:1,samples=220]{.5*sin(deg(3*pi*x))};\addlegendentry{$t=T_3/6$}\addplot[otOrange,thick,domain=0:1,samples=220]{-sin(deg(3*pi*x))};\addlegendentry{$t=T_3/2$}\end{axis}''')
 c.f('modes',r'''\foreach \n in {1,2,3,4}{\begin{scope}[yshift={-1.45*\n cm}]\draw[otMuted](0,0)--(11,0);\draw[otNavy,thick,domain=0:11,samples=200]plot(\x,{.47*sin(deg(\n*pi*\x/11))});\draw[otGreenDark,dashed,domain=0:11,samples=200]plot(\x,{-.47*sin(deg(\n*pi*\x/11))});\fill(0,0)circle(2pt);\fill(11,0)circle(2pt);\node[lab,right]at(11.2,0){$n=\n$};\end{scope}}''')
 c.f('melde',r'''\node[draw=otNavy,fill=otNavyTint,minimum width=1.5cm,minimum height=1cm]at(0,0){Vibreur};\draw[otNavy,thick,domain=.8:10,samples=160]plot(\x,{.5*sin(deg(3*pi*(\x-.8)/9.2))});\draw(10,0)arc(90:0:.5)--(10.5,-2.3);\draw[fill=otNavyTint](10,-2.3)rectangle(11,-3.1);\node at(10.5,-2.7){$M$};\draw[otMuted](10,-.5)circle(.5);\draw[<->,otMuted](.8,1.2)--(10,1.2)node[midway,above]{$L$};\node[lab,text width=6cm,align=left]at(4.5,-2){Tension approximativement uniforme : $T=Mg$.\\Petits déplacements ; poulie idéale.};''')
 c.f('reflexion',r'''\draw[axis](0,0)--(12,0)node[right]{$x$};\draw[thick,otInk](10,-1.3)--(10,2.5);\fill[pattern=north east lines,pattern color=otMuted](10,-1.3)rectangle(10.4,2.5);\draw[otNavy,thick,domain=1:9,samples=160]plot(\x,{exp(-((\x-4)/.7)^2)});\draw[-{Stealth},otNavy,thick](3,1.7)--(5,1.7)node[midway,above]{Incidente};\draw[otGreenDark,dashed,thick,domain=1:9,samples=160]plot(\x,{-exp(-((\x-7)/.7)^2)});\draw[-{Stealth},otGreenDark,thick](8,-1.5)--(6,-1.5)node[midway,below]{Réfléchie inversée};\node[lab]at(10,3){Extrémité fixe};''')
 c.f('partielle',r'''\begin{axis}[width=13.4cm,height=5.7cm,xmin=0,xmax=2,ymin=0,ymax=2,xlabel={$x/\lambda$},ylabel={Amplitude locale / A},axis lines=left,grid=major]\addplot[otNavy,thick,domain=0:2,samples=250]{sqrt(1+.6^2+1.2*cos(deg(4*pi*x)))};\end{axis}''')
 c.intro='Ce chapitre est un approfondissement annoncé, et non une liste de capacités exigibles supplémentaires du programme français de MPSI. Il prolonge les interférences par deux ondes de sens contraires. Les résultats sur la corde sont obtenus par superposition et conditions aux limites, sans introduire d’équation d’onde.'
 c.mapping='Réinvestir la propagation et la superposition de la rubrique 1.6. Approfondissements : nœuds et ventres, réflexion sur une extrémité fixe, modes de la corde fixée aux deux bouts, résonance et mesure de masse linéique. Les lois spécifiques nécessaires sont fournies et expliquées.'
 c.prereq='Chapitres 8 et 9 : onde progressive, phase, somme de deux sinus. Chapitres 4 à 6 : oscillateur, résonance et pertes. Trigonométrie et analyse dimensionnelle.'
 c.method='Écrire les deux ondes avec leurs sens ; imposer les conditions aux extrémités pour tout instant ; séparer facteur spatial et temporel ; identifier les nœuds ; quantifier les fréquences ; confronter le modèle à l’expérience.'
 c.boundary='Les ondes stationnaires ne sont pas explicitement listées dans la rubrique 1.6 du programme MPSI de 2021. La loi c = √(T/μ) est fournie comme modèle de corde idéale ; sa démonstration par équation d’onde est laissée hors de ce chapitre.'
 diagnostic(c,[(r'Quelles directions décrivent $\cos(\omega t-kx)$ et $\cos(\omega t+kx)$ ?',r'Vers +x puis vers -x pour k et ω positifs.'),(r'Rappeler cos(u-v)+cos(u+v).',r'$2\cos u\cos v$.'),(r'Quelle contrainte impose une extrémité fixe ?',r'Le déplacement de cette extrémité est nul à tout instant.'),(r'Une amplitude peut-elle être négative ?',r'Le coefficient algébrique d’un cosinus peut l’être ; l’amplitude physique est sa valeur absolue.'),(r'λ = 0,80 m et c = 40 m/s : donner f.',r'f = c/λ = 50 Hz.'),(r'Quelle est l’unité de la masse linéique ?',r'kg/m : masse par unité de longueur.'),(r'Un maximum d’amplitude en régime forcé peut-il être infini dans un système réel ?',r'Non ; les pertes et les limites du modèle bornent la réponse.'),(r'Deux points dont les coefficients spatiaux sont de signes opposés oscillent comment ?',r'En opposition de phase s’ils partagent le même facteur temporel sinusoïdal.')])
 c.c('Construire une onde stationnaire',box('loi','Deux ondes de même amplitude',r'\[y_+=a\cos(\omega t-kx),\quad y_-=a\cos(\omega t+kx).\]\[y=y_++y_-=2a\cos kx\cos\omega t.\]Les facteurs de position et de temps se séparent. Les lieux d’amplitude nulle restent fixes : cette structure est dite stationnaire.')+sub('Comparer à une onde progressive',r'Une onde progressive sinusoïdale garde une amplitude constante dans le modèle uniforme et présente une phase qui dépend de x. Une onde stationnaire idéale a une amplitude locale dépendant de x ; les points d’un même intervalle entre nœuds oscillent en phase, et ceux d’intervalles voisins en opposition.')+sub('Une somme qui ne translate pas',r'À différentes dates, le profil s’aplatit, change de signe puis retrouve sa forme. Il ne se déplace pas rigidement à une vitesse unique. Pourtant chacune des deux ondes constitutives se propage à c = ω/k. Les appeler « immobiles » individuellement serait incorrect.')+box('methode','Reconnaître la forme',r'Une expression $A(x)\cos(\omega t+\varphi)$ est une onde stationnaire harmonique si A dépend de x et la phase temporelle commune est indépendante de x à un signe près. Vérifier ensuite les conditions aux limites.'))
 c.c('Nœuds, ventres et phases',box('loi',r'Pour $y=2a\cos kx\cos\omega t$',r'Amplitude locale : $A(x)=2a|\cos kx|$. Nœuds : $kx=\pi/2+m\pi$. Ventres : $kx=m\pi$. Deux nœuds voisins sont séparés de λ/2 ; un nœud et le ventre adjacent de λ/4.')+sub('Un déplacement nul à un instant ne suffit pas',r'Lorsque $\cos\omega t=0$, tous les points passent par l’équilibre, y compris les ventres. Un nœud reste immobile à tout instant. Pour le distinguer, observer plusieurs phases ou l’enveloppe des amplitudes.')+sub('La phase entre deux points',r'Les coefficients cos kx de même signe donnent des oscillations en phase. S’ils sont de signes opposés, les oscillations sont en opposition. À un nœud, l’amplitude est nulle et la phase de la vibration n’est pas définie. Il n’existe donc pas une phase continue unique donnant une translation de l’ensemble.')+box('piege','Périodicité du profil et des amplitudes',r'Le facteur signé cos kx a une période λ. Son module a une période λ/2. L’écart entre nœuds vaut donc λ/2, et non λ. Préciser de quelle grandeur on parle.'))
 c.c('La réflexion sur un point fixe',fig('reflexion','Schéma de deux étapes successives : une impulsion réfléchie par une extrémité fixe change de signe. Les deux bosses ne représentent pas un profil unique au même instant.')+sub('Imposer la condition',r'Pour une corde terminée en x = 0 et occupant x < 0, une onde incidente vers +x s’écrit f(t-x/c). Chercher une onde réfléchie vers -x sous la forme g(t+x/c). La condition $y(0,t)=0$ impose g(t) = -f(t), donc\[y=f(t-x/c)-f(t+x/c).\]La réflexion inverse le déplacement au point fixe.')+box('methode','Ne pas généraliser au mauvais signal',r'Cette inversion concerne le déplacement transversal d’une corde fixée. Une surpression acoustique sur un mur rigide n’a pas automatiquement la même loi de réflexion. La condition physique appliquée à la grandeur étudiée détermine le signe.'))
 c.c('Deux extrémités fixes',box('loi','Les conditions valent pour tout t',r'Pour une corde sur [0,L], chercher\[y=A\sin(kx)\cos(\omega t+\varphi).\]La condition en x = 0 est satisfaite. En x = L, une vibration non nulle exige $\sin(kL)=0$, donc\[k_n=\frac{n\pi}{L},\quad\lambda_n=\frac{2L}{n},\quad n=1,2,3,\ldots\]Le cas n = 0 donne le déplacement nul et n’est pas un mode vibrant.')+fig('modes','Les quatre premiers modes. Les deux courbes de chaque ligne représentent des instants en opposition de phase.')+sub('Comptage',r'Le mode n possède n ventres et n + 1 nœuds en comptant les extrémités, donc n - 1 nœuds intérieurs. Les n intervalles de longueur λn/2 sont souvent appelés fuseaux.'))
 c.c('Les fréquences propres de la corde',box('loi','Quantification par la longueur',r'En utilisant la célérité c des ondes progressives constitutives :\[f_n=\frac c{\lambda_n}=\frac{nc}{2L}=nf_1.\]Chaque mode possède une fréquence propre. Le fondamental n = 1 a la plus basse fréquence non nulle ; les autres sont ses harmoniques dans ce modèle non dispersif.')+sub('Un exemple',r'Une corde de longueur 0,80 m avec c = 40 m/s possède f1 = 25 Hz, f2 = 50 Hz et f3 = 75 Hz. Au troisième mode, les nœuds sont en 0, L/3, 2L/3 et L ; les ventres en L/6, L/2 et 5L/6.')+sub('Pourquoi des fréquences discrètes ?',r'Une onde progressive peut avoir une fréquence quelconque dans le modèle illimité. Les deux extrémités fixes exigent qu’un nombre entier de demi-longueurs d’onde tienne dans L. Ce sont les conditions aux limites, combinées à c = λf, qui sélectionnent les modes.')+box('piege','Mode et réponse forcée',r'Les modes sont des mouvements libres admissibles du modèle. Une excitation forcée peut imposer une autre fréquence ; la réponse dépend alors des conditions d’entraînement et des pertes. Une forte amplitude apparaît près des modes lorsque le couplage les excite.'))
 c.c('Tension, masse linéique et célérité',box('loi','Loi fournie du modèle idéal',r'Pour une corde souple, uniforme, faiblement déformée et sous tension constante T :\[c=\sqrt{\frac T\mu},\qquad\mu=\frac m\ell.\]\[f_n=\frac n{2L}\sqrt{\frac T\mu}.\]T est une force en N, μ une masse par unité de longueur en kg/m. On distingue ici T de la période, notée $\mathcal T_n=1/f_n$ si nécessaire.')+sub('Contrôle dimensionnel',r'T/μ a pour unité $(\mathrm{kg\,m\,s^{-2}})/(\mathrm{kg\,m^{-1}})=\mathrm{m^2s^{-2}}$ ; sa racine est bien une vitesse. La tension accroît la force de rappel et donc c ; une masse linéique plus grande accroît l’inertie et réduit c.')+sub('Modifier un son',r'À longueur et masse linéique fixes, doubler f impose de multiplier T par quatre. À tension et masse linéique fixes, diviser L par deux double toutes les fréquences. La variation de longueur dans un instrument agit donc différemment de la variation de tension.')+box('docu','Domaine du modèle',r'Une corde raide, une tension variable ou de grandes amplitudes peuvent décaler les fréquences et briser l’harmonicité exacte. La relation fournie n’est pas universelle pour tout fil réel.'))
 c.c('Observer un mode sans se tromper',fig('stationnaire','Mode 3 : les nœuds restent aux mêmes positions, tandis que les trois fuseaux changent de signe au cours du temps.')+sub('Ce qu’une photographie montre',r'Une corde instantanément rectiligne peut correspondre au passage collectif par l’équilibre, sans absence de vibration. Une pose longue révèle souvent les enveloppes, mais ne donne pas directement la phase. Un stroboscope proche de la fréquence du mouvement peut ralentir le mouvement apparent.')+box('methode','Identifier n',r'Compter les ventres sur la longueur vibrante utile ; vérifier les extrémités effectivement fixes ; mesurer l’écart de plusieurs nœuds ; calculer λ = 2 fois cet écart. En déduire c = λf et vérifier f/n à plusieurs résonances.')+sub('L’alias temporel',r'Un mouvement peut sembler immobile à plusieurs fréquences d’éclairage. Suivre la stabilisation en partant d’une fréquence élevée et utiliser un repère distinct permet de limiter les ambiguïtés. Une image stable ne donne donc pas automatiquement la fréquence fondamentale de la corde.'))
 c.c('L’expérience de Melde',fig('melde','Montage schématique. La longueur utile L est celle de la partie approximativement horizontale et vibrante.')+sub('Un système forcé avec pertes',r'Un vibreur entretient la corde, et une masse suspendue règle approximativement la tension par T = Mg. Balayer la fréquence lentement : de grands fuseaux apparaissent près de certaines fréquences. Le point d’entraînement n’est pas rigoureusement fixe ; assimiler les deux extrémités à des nœuds est une approximation adaptée à de faibles déplacements d’entraînement et à un mode bien établi.')+box('piege','Une amplitude divergente est un défaut du modèle idéal',r'Sans pertes et à une résonance exacte, une description forcée peut prédire une amplification non bornée. Une corde réelle dissipe de l’énergie et atteint une amplitude limitée. Les pertes, le vibreur et l’évolution de la tension interviennent dans cette limite.')+sub('Exploitation',r'Comparer f/n pour plusieurs modes à T fixe ; puis comparer $f_n^2$ à T pour un mode fixé. Une droite attendue dans ce second cas teste le modèle $f_n^2=n^2T/(4L^2\mu)$.'))
 c.c('Plusieurs modes à la fois',box('loi','Superposition guidée',r'Une vibration libre peut être modélisée par une somme de modes :\[y(x,t)=\sum_n A_n\sin\left(\frac{n\pi x}{L}\right)\cos(2\pi f_nt+\varphi_n).\]Chaque terme satisfait les conditions aux deux bouts ; la somme les satisfait aussi. Les coefficients sont fournis ou déterminés à partir des données dans les exercices.')+sub('Interpréter le timbre',r'Deux cordes peuvent avoir le même fondamental mais des proportions d’harmoniques différentes. Le mouvement et le son résultants n’ont pas la même forme temporelle. Le fondamental fixe la période commune du modèle si les modes présents permettent cette période ; les amplitudes et phases des harmoniques contribuent au timbre.')+sub('Les nœuds ne sont plus tous communs',r'La somme des modes 1 et 2 garde les extrémités fixes, mais le milieu L/2 est un ventre du mode 1 et un nœud du mode 2. Il n’est donc pas un nœud de la somme si le mode 1 est présent. Une forme totale compliquée n’est pas nécessairement une onde stationnaire harmonique unique.')+box('methode','Séparer le spectre et la forme spatiale',r'Un capteur placé sur un nœud d’un mode ne détecte pas cette composante même si elle existe ailleurs. La position de mesure peut supprimer certaines raies du spectre enregistré.'))
 c.c('Une réflexion partielle',box('loi','Application guidée de la somme de deux ondes',r'Pour $y=A\cos(\omega t-kx)+rA\cos(\omega t+kx+\phi_r)$ avec $0\leq r\leq1$ :\[A_{\rm loc}^2=A^2[1+r^2+2r\cos(2kx+\phi_r)].\]Les extrema spatiaux valent $A(1+r)$ et $A(1-r)$. Une onde stationnaire parfaite exige r = 1 ; sinon les minima ne sont pas des nœuds immobiles.')+fig('partielle','Enveloppe locale pour r = 0,6 et phase de réflexion nulle : maximum 1,6 A et minimum 0,4 A.')+sub('Une mesure possible',r'Le rapport des amplitudes extrêmes $\mathcal R=A_{\max}/A_{\min}=(1+r)/(1-r)$ donne $r=(\mathcal R-1)/(\mathcal R+1)$. Il faut vérifier que le détecteur mesure une amplitude, et non son carré : la formule de conversion serait alors différente.'))
 c.c('Valider une identification de mode',sub('Trois contrôles indépendants',r'La géométrie donne n et λn = 2L/n. La fréquence mesurée et λn donnent c. La tension et la masse linéique donnent une seconde prédiction $\sqrt{T/\mu}$. Comparer ces trois éléments rend l’identification plus robuste qu’un seul comptage de fuseaux.')+box('loi','Incertitude de masse linéique',r'En identifiant un mode n :\[\mu=\frac{n^2T}{4L^2f_n^2}.\]Pour T, L et f indépendants et des incertitudes petites :\[\frac{u(\mu)}\mu=\sqrt{\left(\frac{u(T)}T\right)^2+4\left(\frac{u(L)}L\right)^2+4\left(\frac{u(f_n)}{f_n}\right)^2}.\]Le nombre n est ici identifié exactement ; une erreur de mode est une erreur de modèle, pas une petite incertitude.')+sub('Une conclusion expérimentale',r'Si les rapports f/n ne coïncident pas dans les incertitudes, rechercher une longueur utile mal définie, un entraînement trop fort, une tension non uniforme, une corde raide ou une mauvaise identification. Un ajustement numérique précis ne répare pas une condition aux limites incorrecte.')+box('docu','Place de cet approfondissement',r'Ces outils prolongent les compétences de superposition et d’analyse expérimentale de MPSI. Les lois propres aux cordes ne sont pas présentées comme des exigences additionnelles du programme national.'))
 c.tp_title='Identifier la masse linéique d’une corde'
 c.tp=fig('melde','Choisir une faible amplitude et mesurer la longueur vibrante, distincte de la longueur totale de la corde.')+sub('Protocole',r'Fixer L = 0,80 m et une tension T = 4,00 N. Rechercher trois résonances et compter les ventres. Relever f, puis ajuster f en fonction de n ; la pente donne c/(2L). Déduire μ et comparer à une pesée d’une longueur connue de corde.')+sub('Jeu simulé et correction',r'Pour n = 1 ; 2 ; 3, on donne f = 25,0 ; 50,0 ; 75,0 Hz. La pente vaut 25,0 Hz, c = 40,0 m/s et μ = T/c² = 0,00250 kg/m = 2,50 g/m. Une corde de 2,00 m pèserait donc 5,00 g dans ce modèle.')+box('methode','Contrôle complémentaire',r'À n fixé, faire varier T et tracer f² en fonction de T. Une pente conforme à $n^2/(4L^2\mu)$ valide une autre prédiction. Documenter les incertitudes, la condition d’entraînement et les écarts aux extrémités. Les données précédentes sont simulées.')
 c.num_title='Voir une superposition de modes'
 c.num=r'''La simulation ne résout pas d’équation d’onde : elle superpose des modes fournis satisfaisant les conditions aux extrémités.
\begin{verbatim}
import numpy as np
import matplotlib.pyplot as plt
L, c = 0.8, 40.
x = np.linspace(0, L, 801)
f1 = c/(2*L)
amplitudes = {1: 0.01, 2: 0.004, 3: 0.002}
def y(t):
    return sum(A*np.sin(n*np.pi*x/L)*
        np.cos(2*np.pi*n*f1*t)
        for n,A in amplitudes.items())
profiles = {}
for t in (0., 0.005, 0.01, 0.02):
    profiles[t] = y(t)
    plt.plot(x, y(t)*1000, label=f"t={t}s")
plt.xlabel("x (m)"); plt.ylabel("y (mm)")
plt.grid(); plt.legend(); plt.tight_layout()
\end{verbatim}
Vérifier y(0,t) = y(L,t) = 0 à la précision numérique. La période commune est 1/f1 = 40 ms ; à 20 ms, les modes impairs changent de signe mais le mode 2 retrouve le sien. Le profil total n’est donc pas simplement l’opposé du profil initial. Placer un capteur en L/2 supprime le mode 2 de son enregistrement.
'''
 bilan(c,r'Deux ondes opposées de même amplitude produisent une structure stationnaire. Corde fixe-fixe : $\lambda_n=2L/n$, $f_n=nc/(2L)$, n ≥ 1. Loi fournie : $c=\sqrt{T/\mu}$. Mode n : n ventres et n + 1 nœuds en comptant les extrémités.',r'Écrire les deux ondes, appliquer les conditions pour tout instant, identifier les facteurs spatiaux et les phases, compter les fuseaux, puis comparer fréquences et célérité. Annoncer les approximations de la corde idéale.',r'Confondre nœud et passage instantané par l’équilibre ; compter seulement les nœuds intérieurs ; prendre λ au lieu de λ/2 entre nœuds ; employer n = 0 comme fondamental ; identifier une fréquence sans vérifier le mode.')
 c.td_titles=['Reconnaître une onde stationnaire','Nœuds et ventres','Modes d’une corde','Tension et masse linéique','Phases et superpositions','Mesures et incertitudes','Réflexion et entraînement','Discuter le modèle']
 exercices(c,[
 ('Deux sens contraires',r'Additionner $a\cos(\omega t-kx)$ et $a\cos(\omega t+kx)$. La somme translate-t-elle son profil ?',r'$y=2a\cos kx\cos\omega t$. Les facteurs spatial et temporel se séparent ; les nœuds sont fixes. Le profil ne se translate pas rigidement.'),
 ('Une amplitude locale',r'$y=4\cos kx\cos\omega t$ mm. Donner l’amplitude en x = 0, λ/8 et λ/4.',r'Amplitudes : 4 mm ; $4|\cos(\pi/4)|=2\sqrt2$ mm ; 0. Le point λ/4 est un nœud.'),
 ('Un vrai nœud',r'À un instant, toute une corde est droite. Peut-on affirmer que tous ses points sont des nœuds ?',r'Non. Les points d’un mode peuvent passer simultanément par l’équilibre. Un nœud est immobile à tout instant ; il faut observer l’évolution ou l’enveloppe.'),
 ('Espacements',r'Deux nœuds consécutifs sont séparés de 0,25 m. Donner λ et l’écart nœud-ventre adjacent.',r'λ = 0,50 m ; l’écart nœud-ventre vaut λ/4 = 0,125 m. La période spatiale du module de l’amplitude est λ/2.'),
 ('Opposition entre fuseaux',r'Deux points sont dans deux fuseaux voisins d’un mode. Quelle est leur phase relative si aucun n’est un nœud ?',r'Les facteurs spatiaux sont de signes opposés : les déplacements sont en opposition de phase, décalés de π. Leurs amplitudes peuvent être différentes.'),
 ('Compter un mode',r'Une corde fixe aux deux bouts présente quatre ventres. Donner n, les nœuds totaux et les nœuds intérieurs.',r'n = 4 ; cinq nœuds au total, dont trois intérieurs. Les deux extrémités sont comptées comme nœuds.'),
 ('Le fondamental',r'L = 0,80 m, c = 40 m/s. Donner f1 et les trois harmoniques suivantes.',r'f1 = c/(2L) = 25 Hz ; f2 = 50 Hz, f3 = 75 Hz, f4 = 100 Hz. Ces fréquences sont équidistantes dans le modèle non dispersif.'),
 ('Une longueur d’onde modale',r'L = 1,20 m et n = 3. Donner λ3 et les positions des nœuds.',r'λ3 = 2L/3 = 0,80 m. Les nœuds sont x = 0 ; 0,40 ; 0,80 ; 1,20 m. Il existe trois ventres, au milieu des intervalles.'),
 ('Un mode observé',r'Une corde de 1,00 m présente cinq fuseaux à 100 Hz. Déterminer c et f1.',r'n = 5 ; λ5 = 2L/5 = 0,40 m. c = λ5f5 = 40 m/s et f1 = f5/5 = 20 Hz.'),
 ('Calculer la masse linéique',r'Une corde de 2,00 m a une masse de 5,00 g. Donner μ et c sous T = 4,00 N.',r'μ = 0,005/2 = 0,00250 kg/m. $c=\sqrt{4/0{,}0025}=40$ m/s. Convertir les grammes en kilogrammes avant la racine.'),
 ('Accorder à l’octave',r'À L et μ constants, par quel facteur multiplier T pour doubler f1 ?',r'f1 varie comme √T. Il faut T′/T = 4. Doubler la tension seule ne multiplie la fréquence que par √2.'),
 ('Raccourcir la corde',r'À T et μ constants, quelle longueur donne une fréquence fondamentale égale à 3/2 de l’ancienne ?',r'f1 est inversement proportionnel à L. Donc L′ = (2/3)L. Les conditions de fixation et la longueur utile doivent suivre ce nouveau modèle.'),
 ('Un mode écrit',r'$y=A\sin(3\pi x/L)\cos\omega_3t$. Donner l’amplitude au milieu et à L/3.',r'Au milieu, sin(3π/2) = -1 : amplitude A, avec un coefficient signé -A. À L/3, sin π = 0 : nœud. Le milieu est un ventre, malgré le signe négatif.'),
 ('Deux modes au milieu',r'$y=A\sin(\pi x/L)\cos\omega_1t+B\sin(2\pi x/L)\cos2\omega_1t$. Que mesure un capteur en L/2 ?',r'$y(L/2,t)=A\cos\omega_1t$ ; le mode 2 a un nœud au milieu. L’absence de sa raie à ce capteur ne signifie pas son absence sur toute la corde.'),
 ('Une période commune',r'Une corde contient seulement les modes 2 et 3, de fréquences 2f1 et 3f1. Donner la période commune minimale.',r'Les rangs 2 et 3 sont premiers entre eux : la période est 1/f1, même si la fondamentale elle-même est absente du spectre. La forme ne retrouve pas généralement sa valeur après 1/(2f1).'),
 ('Identifier μ sur un mode',r'L = 0,80 m, T = 4,00 N, n = 2 et f2 = 50,0 Hz. Calculer μ.',r'$\mu=n^2T/(4L^2f_n^2)=16/(4\times0{,}64\times2500)=0{,}00250$ kg/m. Une erreur sur n serait amplifiée par son carré.'),
 ('Une incertitude relative',r'Pour E16, les incertitudes relatives indépendantes sont u(T)/T = 1 %, u(L)/L = 0,5 %, u(f)/f = 0,2 %. Donner u(μ)/μ.',r'$\sqrt{0{,}01^2+4(0{,}005)^2+4(0{,}002)^2}=0{,}01470$, soit 1,47 %. Donc u(μ) ≈ 0,0367 g/m.'),
 ('Une droite de fréquences',r'À longueur fixe, un ajustement donne f = 30,0 n en Hz. L = 1,00 m et T = 9,00 N. Donner c et μ.',r'La pente vaut c/(2L), donc c = 60 m/s. μ = T/c² = 9/3600 = 0,00250 kg/m. Une ordonnée notable à n = 0 demanderait de discuter les conditions aux limites.'),
 ('Un point fixe impose le signe',r'Une corde x < 0 reçoit $f(t-x/c)$ vers x = 0. Trouver l’onde réfléchie imposant y(0,t) = 0.',r'Elle se propage vers -x et vaut $-f(t+x/c)$. La somme s’annule à x = 0 pour tout t. Le signe moins traduit l’inversion du déplacement.'),
 ('Une réflexion partielle',r'Les amplitudes spatiales extrêmes mesurées sont 8 mm et 2 mm. Déduire r et A dans le modèle de réflexion partielle.',r'$r=(8/2-1)/(8/2+1)=3/5=0{,}60$. $A=(8+2)/2=5$ mm. L’onde réfléchie a l’amplitude rA = 3 mm ; les minima ne sont pas des nœuds parfaits.'),
 ('Une tension par une masse',r'Une masse M = 0,200 kg tend une corde de μ = 1,00 g/m. Avec g = 9,81 m/s², calculer c et f1 pour L = 1 m.',r'T = Mg = 1,962 N. c = √1962 = 44,294 m/s. f1 = 22,147 Hz. Le calcul suppose une poulie idéale et une tension uniforme sur la partie vibrante.'),
 ('Le mauvais mode',r'On observe n = 3 mais on l’identifie par erreur comme n = 2 dans le calcul de μ. Quel rapport obtient-on entre μ estimée et vraie ?',r'À T, L et f fixés, μ varie comme n². μestimée/μvraie = 4/9. Cette erreur ne se corrige pas en réduisant la seule incertitude de fréquence.'),
 ('Un modèle mis en défaut',r'Les fréquences mesurées sont 30,0 ; 61,0 ; 94,0 Hz pour les trois premiers modes, avec u(f) = 0,1 Hz. La corde idéale harmonique est-elle compatible ?',r'Les rapports f/n sont 30,0 ; 30,5 ; 31,333 Hz et les écarts dépassent largement les incertitudes correspondantes. Rechercher une raideur, une tension variable, une longueur efficace dépendant du mode ou une erreur d’identification.'),
 ('Une résonance forcée',r'Un calcul idéal prédit une amplitude infinie à une fréquence propre. Quelles hypothèses revoir avant de comparer à l’expérience ?',r'Inclure les pertes, la dynamique du vibreur, les conditions réelles aux extrémités et les limites des petites déformations. Une divergence du régime forcé sans pertes signale l’absence de solution permanente bornée, pas une amplitude physique infinie mesurée.')])
 c.d('Identifier une corde avec plusieurs modes',r'Pour une longueur L = 0,900 m et une tension T = 8,00 N, on mesure les résonances 40,0 ; 80,0 ; 120,0 Hz, avec respectivement 1 ; 2 ; 3 ventres.'+qs(r'Identifier le fondamental, la célérité et μ.',r'On double la masse suspendue qui règle T, sans modifier L ni μ. Prédire les trois nouvelles fréquences.',r'On souhaite f1 = 60,0 Hz en conservant T initiale. Quelle longueur choisir ?',r'Proposer deux méthodes indépendantes pour tester μ.',r'Pourquoi le seul rapport de deux fréquences ne suffit-il pas à identifier les rangs si l’on ne voit pas les fuseaux ?'),'1. Exploiter la pente f(n). 2. Une fréquence varie comme √T et 1/L. 3. Des modes peuvent manquer dans un spectre.',r'f1 = 40,0 Hz ; c = 2Lf1 = 72,0 m/s ; μ = 8/72² = 0,00154321 kg/m = 1,543 g/m. Si T double, les fréquences sont multipliées par √2 : 56,57 ; 113,14 ; 169,71 Hz. Pour f1 = 60 Hz à c inchangée, L′ = c/(2f1) = 0,600 m. Une pesée de longueur connue donne μ directement ; une variation de T à n fixé permet d’exploiter la pente de f²(T). Le rapport 2 entre deux fréquences pourrait correspondre aux rangs 1 et 2, ou 2 et 4, etc. Compter les fuseaux ou repérer plusieurs modes consécutifs lève cette ambiguïté. La cohérence de plusieurs prédictions est plus convaincante qu’un seul accord numérique.')
 c.d('Déterminer la phase d’une réflexion',r'Une corde semi-infinie porte $y=A\cos(\omega t-kx)+rA\cos(\omega t+kx+\phi_r)$, avec A > 0 et 0 < r < 1. On mesure Amax = 9 mm, Amin = 3 mm, et des maxima d’enveloppe en x = 0,10 m puis 0,40 m.'+qs(r'Déterminer A et r.',r'Déterminer λ, k puis c si f = 50 Hz.',r'Donner φr modulo 2π en utilisant le maximum à 0,10 m.',r'Pourquoi cette onde n’est-elle pas parfaitement stationnaire ? Peut-on parler de nœuds ?',r'Si le détecteur mesurait le carré de l’amplitude, comment adapter l’exploitation ?'),'1. Addition et différence des extrema. 2. Deux maxima d’enveloppe sont séparés de λ/2. 3. Le maximum vérifie 2kx+φr = 2mπ.',r'A = (9 + 3)/2 = 6 mm ; r = (9 - 3)/(9 + 3) = 0,50. L’écart 0,30 m vaut λ/2, donc λ = 0,60 m et k = 10π/3 rad/m. c = λf = 30 m/s. Le maximum en 0,10 m donne $\phi_r=-2k(0{,}10)=-2\pi/3$ modulo 2π. Les amplitudes opposées ne sont pas égales ; les minima restent à 3 mm et ne sont donc pas des points immobiles. Une partie progressive subsiste dans cette superposition. Si les valeurs mesurées étaient proportionnelles à l’amplitude au carré, il faudrait prendre leurs racines avant de former le rapport $(A_{\max}-A_{\min})/(A_{\max}+A_{\min})$. Toujours identifier la réponse du détecteur.')
 c.d('Un entraînement à une extrémité',r'Une corde sur [0,L] est fixée en x = L et entraînée en x = 0 par $y(0,t)=a\cos\omega t$. Dans un modèle sans pertes, on cherche une réponse $y=B\sin[k(L-x)]\cos\omega t$, avec k = ω/c.'+qs(r'Vérifier la condition en L, puis déterminer B lorsque sin(kL) ≠ 0.',r'Écrire l’amplitude locale et identifier les fréquences où le calcul échoue.',r'Pourquoi l’extrémité entraînée n’est-elle pas un nœud exact ?',r'Que faut-il comprendre physiquement quand sin(kL) tend vers zéro ?',r'Comparer à l’approximation des deux extrémités fixes près d’une résonance de faible entraînement.'),'1. Évaluer y en x = 0. 2. Le dénominateur gouverne l’amplification. 3. Le modèle sans pertes n’a pas de régime borné à la résonance.',r'La condition en L est automatiquement satisfaite. En 0, $B\sin(kL)=a$, donc $y=a\sin[k(L-x)]\cos\omega t/\sin(kL)$. L’amplitude locale est $a|\sin[k(L-x)]/\sin(kL)|$. Le calcul de réponse permanente bornée échoue à kL = nπ, soit f = nc/(2L). L’extrémité entraînée a une amplitude a non nulle : elle n’est pas un nœud. Près d’une résonance, les amplitudes intérieures peuvent être grandes devant a ; l’extrémité paraît alors presque immobile à l’échelle de l’enveloppe, d’où l’approximation fixe-fixe. Les pertes et le vibreur limitent le maximum réel. La divergence ne doit jamais être présentée comme une amplitude expérimentale infinie.')
 c.dm_title='DM — Accorder une corde'
 c.dm=r'Une corde souple a une longueur vibrante L = 0,650 m et une masse linéique μ = 1,20 g/m. On fournit c = √(T/μ). Elle est assimilée à une corde fixée aux deux extrémités.'+sub('A. Fréquence cible — 8 points',qs(r'Établir λn et fn avec les conditions aux limites. (4)',r'On souhaite f1 = 200 Hz. Calculer c et T nécessaires. (4)'))+sub('B. Modifier la note — 6 points',qs(r'À tension constante, quelle longueur donne f1 = 300 Hz ? (3)',r'À longueur initiale constante, quelle tension donne 300 Hz ? (3)'))+sub('C. Observation — 6 points',qs(r'À la fréquence du mode 3 pour les réglages initiaux, donner positions des nœuds et ventres. (4)',r'Un capteur placé en L/2 détecte-t-il ce mode ? Et le mode 2 ? (2)'))
 c.dm_sol=sub('A — 8 points',r'Une forme $A\sin(kx)\cos\omega t$ impose kL = nπ, n ≥ 1, donc λn = 2L/n et fn = nc/(2L) (4). c = 2Lf1 = 260 m/s. T = μc² = 0,00120 × 260² = 81,12 N (4).')+sub('B — 6 points',r'À c fixe : L′ = c/(2 × 300) = 0,4333 m (3). À L initial fixe, c′ = 390 m/s et T′ = μc′² = 182,52 N = 2,25T (3).')+sub('C — 6 points',r'f3 = 600 Hz. Nœuds x = 0 ; 0,2167 ; 0,4333 ; 0,650 m. Ventres x = 0,1083 ; 0,3250 ; 0,5417 m (4). Le milieu est un ventre du mode 3 et un nœud du mode 2 : il détecte le premier, mais pas le second dans le modèle idéal (2).')
 c.ds_title='DS — Étudier une corde de Melde'
 c.ds=[sub('A. Superposition — 6 points',r'On donne $y_1=a\cos(\omega t-kx)$ et $y_2=-a\cos(\omega t+kx)$.'+qs(r'Exprimer leur somme comme produit de deux sinus. (2)',r'Identifier les nœuds et l’écart entre deux nœuds voisins. (2)',r'Pourquoi x = 0 reste-t-il fixe ? (2)'))+sub('B. Modes — 9 points',r'Une corde de L = 1,20 m et μ = 2,00 g/m est soumise à T = 8,00 N. On fournit c = √(T/μ).'+qs(r'Calculer c puis les fréquences des modes 1, 2 et 3. (3)',r'Un régime à quatre ventres est observé : donner sa fréquence et ses nœuds intérieurs. (3)',r'La tension est multipliée par 1,44. Que deviennent les fréquences et pourquoi ? (3)')),
 sub('C. Réflexion partielle — 5 points',r'Un autre montage donne Amax = 10 mm et Amin = 2 mm. On fournit Amax = A(1+r), Amin = A(1-r).'+qs(r'Déterminer A et r. (2)',r'Peut-on appeler les minima des nœuds ? (1)',r'Les maxima voisins sont distants de 0,40 m à f = 80 Hz. Déterminer λ et c. (2)'))]
 c.ds_sol=[sub('A — 6 points',r'$y=2a\sin\omega t\sin kx$ par l’identité cos(u-v) - cos(u+v) (2). Nœuds kx = mπ, écart π/k = λ/2 (2). En x = 0, les deux ondes se compensent à tout instant ; la réflexion de déplacement a le signe imposé par le point fixe (2).')+sub('B — 9 points',r'c = √(8/0,002) = 63,2456 m/s. f1 = 26,3523 Hz, f2 = 52,7046 Hz, f3 = 79,0569 Hz (3). Quatre ventres : n = 4, f4 = 105,409 Hz ; nœuds intérieurs x = 0,30 ; 0,60 ; 0,90 m (3). c et tous les fn sont multipliés par √1,44 = 1,20 ; les modes conservent leurs positions relatives si L ne change pas (3).'),sub('C — 5 points',r'A = (10 + 2)/2 = 6 mm et r = (10 - 2)/(10 + 2) = 2/3 (2). Les minima d’amplitude 2 mm ne sont pas des points immobiles ; ce ne sont pas des nœuds parfaits (1). L’écart des maxima est λ/2 = 0,40 m ; λ = 0,80 m et c = λf = 64,0 m/s (2).')]
 c.hints='E04 : l’amplitude locale a une période λ/2. E13 : prendre la valeur absolue du coefficient spatial. E16 : isoler μ dans fn. E22 : n apparaît au carré.'
 c.eval_hints='DM : convertir la masse linéique en kg/m. DS : appliquer les conditions aux limites pour tout instant ; conserver assez de chiffres sur c avant de calculer les fréquences.'
 c.source('TD MPSI publié — Corde de Melde','https://etienne-thibierge.fr/cours_mpsi/O4_ondes_td-enonce.pdf','Étienne Thibierge, lycée Corneille, MPSI 2, TD O4, exercice 8, questions 1 à 3, p. 6–7.',r'Traiter les questions à partir des deux ondes fournies. Conserver la convention de phase du document et imposer les extrémités fixes.',r'La somme est $\xi=2a\cos(kz+\varphi)\cos\omega t$. Nœuds : $kz+\varphi=\pi/2+m\pi$ ; ventres : $kz+\varphi=m\pi$. Les nœuds sont espacés de $\lambda/2$. La valeur $\varphi=-\pi/2$ convient à z = 0 ; la condition en L impose $k_n=n\pi/L$, puis $f_n=nc/(2L)$. Au mode 3, il y a trois ventres et quatre nœuds, extrémités comprises. Ce parcours est un approfondissement identifié.')
 c.source('Support expérimental — Observer des modes','https://www.physagreg.fr/agreg-montage-physique-36-ondes-stationnaires.php','Physagreg, montage de physique n°36. Sélection : corde de Melde uniquement ; niveau d’origine agrégation.',r'Identifier les mesures de longueur, tension et fréquence. Adapter seulement le protocole de corde à ce chapitre ; laisser les autres dispositifs hors du parcours.',r'Le test f en fonction de 1/L à n fixé donne une pente $nc/2$. Le modèle fourni $c=\sqrt{Mg/\mu}$ permet ensuite d’identifier μ. Distinguer une observation de structure stationnaire d’une forte amplitude de résonance.')
 c.next='La suite de l’ouvrage commencera par la description et le paramétrage du mouvement d’un point, chapitre 11 du plan annuel.'
 c.check('mu-D1',8/72**2,.0015432098765432098)
 c.check('tension-DM',.0012*260**2,81.12)
 c.check('f4-DS',4*sqrt(4000)/(2*1.2),105.40925533894598)
 c.check('u-mu-rel',sqrt(.01**2+4*.005**2+4*.002**2),.014696938456699069)
 return c
